/* Worldseed Engine — procedural soundscape (P9).
 *
 * The engine has no recorded audio and no third-party audio runtime. Every
 * sound is generated by our own C17 code: a small fixed voice pool of sine
 * oscillators with an attack/decay envelope, mixed to an interleaved 16-bit PCM
 * buffer at 48 kHz. The same code that renders a preview frame can render a
 * short WAV so the sound is real, inspectable evidence rather than a claim.
 *
 * The soundscape is event-linked: it is driven by the same real life events the
 * cinematic director observes (docs/09 "Ses eşleme: gerçek dünya ses kaynağı").
 * A birth, a death, a kill or a forage each maps to a distinct voice; nothing is
 * played without a real event behind it.
 *
 * The module is deterministic: the same event sequence produces a bit-identical
 * PCM buffer, so an automated test can hash it.
 */
#ifndef WS_AUDIO_SOUNDSCAPE_H
#define WS_AUDIO_SOUNDSCAPE_H

#include <stddef.h>
#include <stdint.h>

#include "../core/ws_result.h"
#include "../world/ws_event.h"

#define WS_AUDIO_SAMPLE_RATE 48000u
#define WS_AUDIO_MAX_VOICES 32u
#define WS_AUDIO_KIND_COUNT 4u

typedef struct ws_audio_voice {
    int active;
    double phase;      /* radians */
    double freq;       /* Hz */
    double amp;        /* 0..1 current envelope level */
    double amp_target; /* 0..1 peak for this voice */
    double decay;      /* envelope decay rate, 1/s */
    double pan;        /* -1 left .. +1 right, from world x offset */
} ws_audio_voice;

typedef struct ws_audio {
    uint32_t sample_rate;
    ws_audio_voice voices[WS_AUDIO_MAX_VOICES];
    double last_trigger_s[WS_AUDIO_KIND_COUNT]; /* world time of the last voice */
    double master_gain; /* 0..1 user volume multiplier (settings menu) */
    uint64_t events_played;
    uint64_t events_skipped; /* real events suppressed by the per-kind cooldown */
    uint64_t voices_dropped; /* events that found every voice busy */
    uint64_t samples_rendered;
} ws_audio;

void ws_audio_init(ws_audio *a, uint32_t sample_rate);

/* Trigger a sound for a real life event at world time `time_s`. `pan` is -1..+1.
 * A kind with no mapping plays nothing and is not counted. A kind retriggers at
 * most once per its cooldown window, so a flood of one event type (e.g. the
 * many grazing events) does not saturate the pool into a drone; such a repeat
 * is counted in events_skipped. Returns WS_OK. */
ws_result ws_audio_trigger_event(ws_audio *a, uint8_t kind, double pan,
                                 double time_s);

/* Number of currently sounding voices (for tests/evidence). */
uint32_t ws_audio_active_voices(const ws_audio *a);

/* Mix the next `frames` sample frames into `out` (interleaved stereo int16,
 * 2 * frames samples). Adds to nothing: the buffer is written, not summed.
 * Deterministic for a given voice state and frame count. */
ws_result ws_audio_mix(ws_audio *a, int16_t *out, uint32_t frames);

/* Total sound samples produced since init. */
uint64_t ws_audio_samples_rendered(const ws_audio *a);

/* Master volume as a 0..1 gain. Values outside the range are clamped. Setting
 * the gain changes only the mixed output, never the voice state or the world. */
void ws_audio_set_master_gain(ws_audio *a, double gain);

/* Current master gain (0..1). Returns 1.0 for a NULL pointer. */
double ws_audio_master_gain(const ws_audio *a);

/* Write an interleaved stereo int16 PCM buffer as a canonical 44-byte-header
 * 16-bit WAV. Returns WS_OK, or an error when the file cannot be opened. */
ws_result ws_audio_write_wav(const char *path, const int16_t *pcm,
                             uint32_t frames, uint32_t sample_rate);

#endif /* WS_AUDIO_SOUNDSCAPE_H */
